/**
 * The four display faces, inlined as data URIs.
 *
 * Fetching them at render time raced the renderer and hung frames, so the bytes
 * live here instead — the fonts are present the moment the page parses, with no
 * network and nothing to wait on. Regenerate with tools/embed_fonts.py after
 * swapping a typeface.
 */
export const FONT_CSS = `
@font-face{font-family:'AntonEdit';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'ArchivoBlackEdit';font-style:normal;font-weight:400;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'BarlowCondEdit';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'SpaceMonoEdit';font-style:normal;font-weight:700;font-display:block;src:url(data:font/woff2;base64,) format('woff2');}
`;
